import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [clients, setClients] = useState([]);
  const [proveidors, setProveidors] = useState([]);
  const [products, setProducts] = useState([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState(null);

  const token = localStorage.getItem("token");

  const headers = {
    Accept: "application/json",
    Authorization: token ? `Bearer ${token}` : undefined,
  };

  /* ---------------- FETCH ---------------- */

  const fetchOrders = async () => {
    const res = await fetch("http://localhost/api/comandes", { headers });
    const json = await res.json();
    setOrders(json.dades || []);
  };

  const fetchClients = async () => {
    const res = await fetch("http://localhost/api/clients", { headers });
    const json = await res.json();
    setClients(json.dades || []);
  };

  const fetchProveidors = async () => {
    const res = await fetch("http://localhost/api/proveidors", { headers });
    const json = await res.json();
    setProveidors(json.dades || []);
  };

  const fetchProducts = async () => {
    const res = await fetch("http://localhost/api/productes", { headers });
    const json = await res.json();
    setProducts(json.dades || []);
  };

  useEffect(() => {
    Promise.all([
      fetchOrders(),
      fetchClients(),
      fetchProveidors(),
      fetchProducts(),
    ])
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  /* ---------------- MODAL ---------------- */

  const openCreateModal = () => {
    setEditingOrder({
      data: new Date().toISOString().slice(0, 10),
      tipus: "",
      client_id: "",
      proveidor_id: "",
      detalls: [],
    });
    setShowModal(true);
  };

  const addProduct = (productId) => {
    const product = products.find(p => p.id == productId);
    if (!product) return;

    setEditingOrder(prev => {
      const exists = prev.detalls.find(d => d.producte_id === product.id);
      if (exists) {
        return {
          ...prev,
          detalls: prev.detalls.map(d =>
            d.producte_id === product.id
              ? { ...d, quantitat: d.quantitat + 1 }
              : d
          ),
        };
      }

      return {
        ...prev,
        detalls: [
          ...prev.detalls,
          { producte_id: product.id, nom: product.nom, quantitat: 1 },
        ],
      };
    });
  };

  /* ---------------- SAVE ---------------- */

  const handleSave = async () => {
    if (!token) return alert("No autenticat");

    const payload = {
      data: editingOrder.data,
      tipus: editingOrder.tipus,
      client_id: editingOrder.client_id || null,
      proveidor_id: editingOrder.proveidor_id || null,
      detalls: editingOrder.detalls.map(d => ({
        producte_id: d.producte_id,
        quantitat: d.quantitat,
      })),
    };

    const res = await fetch("http://localhost/api/comandes", {
      method: "POST",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });

    const json = await res.json();
    if (!res.ok || json.exit === false) return alert(json.missatge);

    setOrders([...orders, json.dades]);
    setShowModal(false);
  };

  /* ---------------- DELETE ---------------- */

  const handleDelete = async (id) => {
    if (!window.confirm("Eliminar comanda?")) return;

    const res = await fetch(`http://localhost/api/comandes/${id}`, {
      method: "DELETE",
      headers,
    });

    const json = await res.json();
    if (!res.ok) return alert(json.missatge);

    setOrders(orders.filter(o => o.id !== id));
  };

  /* ---------------- RENDER ---------------- */

  if (loading) return <Spinner className="mt-5" />;
  if (error) return <Alert variant="danger">{error}</Alert>;

  return (
    <div className="mt-4">
      <h2>Comandes</h2>
      <Button onClick={openCreateModal}>Crear Comanda</Button>

      <Table striped bordered className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Proveïdor</th>
            <th>Tipus</th>
            <th>Data</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {orders.map(o => (
            <tr key={o.id}>
              <td>{o.id}</td>
              <td>{o.client?.nom || "-"}</td>
              <td>{o.proveidor?.nom || "-"}</td>
              <td>{o.tipus}</td>
              <td>{new Date(o.data).toLocaleDateString()}</td>
              <td>
                <Button size="sm" variant="danger" onClick={() => handleDelete(o.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {showModal && (
        <div className="modal show d-block">
          <div className="modal-dialog modal-lg">
            <div className="modal-content">

              <div className="modal-header">
                <h5>Nova Comanda</h5>
                <button className="btn-close" onClick={() => setShowModal(false)} />
              </div>

              <div className="modal-body">
                <select className="form-control mb-2" onChange={e => setEditingOrder({ ...editingOrder, client_id: e.target.value })}>
                  <option value="">Client</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.nom}</option>)}
                </select>

                <select className="form-control mb-2" onChange={e => setEditingOrder({ ...editingOrder, proveidor_id: e.target.value })}>
                  <option value="">Proveïdor</option>
                  {proveidors.map(p => <option key={p.id} value={p.id}>{p.nom}</option>)}
                </select>

                <input className="form-control mb-2" placeholder="Tipus (purchase/sale)"
                  onChange={e => setEditingOrder({ ...editingOrder, tipus: e.target.value })} />

                <input type="date" className="form-control mb-3"
                  value={editingOrder.data}
                  onChange={e => setEditingOrder({ ...editingOrder, data: e.target.value })} />

                <hr />
                <h5>Productes</h5>

                <select className="form-control mb-2" onChange={e => addProduct(e.target.value)}>
                  <option value="">Afegir producte</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.nom}</option>)}
                </select>

                {editingOrder.detalls.map(d => (
                  <div key={d.producte_id} className="d-flex mb-2">
                    <div className="flex-grow-1">{d.nom}</div>
                    <input
                      type="number"
                      min="1"
                      value={d.quantitat}
                      onChange={e =>
                        setEditingOrder({
                          ...editingOrder,
                          detalls: editingOrder.detalls.map(x =>
                            x.producte_id === d.producte_id
                              ? { ...x, quantitat: Number(e.target.value) }
                              : x
                          ),
                        })
                      }
                    />
                  </div>
                ))}
              </div>

              <div className="modal-footer">
                <Button onClick={handleSave}>Guardar</Button>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default OrdersList;
